cd /tmp/opencode && cat > mandate.py <<'EOF'
import sys
sys.path.insert(0, "/app/categorizationapp")
from categorizationapp import app

def run(bank, acc, desc, amt, typ):
    payload = {"bank": bank, "acc_type": acc, "accountUID":"u","accountHolder":"",
      "transactions":[{"description":desc,"remark":"","amount":amt,"balanceAfterTransaction":1000,"type":typ}]}
    with app.test_client() as c:
        o = c.post("/categorizeTransaction", json=payload).get_json()["response"][0]
    print(f"{bank:9s} {desc:28s} {amt:>4} {typ:6s} -> {o['transactionCategory']}")

for bank in ["AXIS","INDUSIND"]:
    for desc in ["ACH MANDATE","NACH E MANDATE","MANDATE TOKEN","NACH MANDATE VERIFICATION","ACH MANDATE CHARGES"]:
        for amt in [1,2,5]:
            for typ in ["DEBIT","CREDIT"]:
                run(bank, "SAVING", desc, amt, typ)
EOF
python3 mandate.py 2>&1 | grep "\->"

cd /tmp/opencode && python3 - <<'EOF'
def load(p):
    d={}
    for line in open(p):
        parts=line.rstrip("\n").split("|")
        key=tuple(parts[:6]); d[key]=tuple(parts[6:])
    return d
b=load("before.txt"); a=load("after.txt")
assert set(b)==set(a)
from collections import Counter
c=Counter()
for k in b:
    if b[k]!=a[k]:
        c[(k[0],k[2],b[k],a[k])]+=1
for (bank,desc,bv,av),n in sorted(c.items()):
    print(f"{n:4d} {bank:9s} {desc[:45]:45s} {bv} -> {av}")
print("total changed:", sum(c.values()), "of", len(b))
EOF

